+func relationshipChangesForVersion(
+	ctx context.Context,
+	changes <-chan datastore.RevisionChanges,
+	errs <-chan error,
+	version RelationshipVersion,
+) (<-chan datastore.RevisionChanges, <-chan error) {
+	filteredChanges := make(chan datastore.RevisionChanges)
+	filteredErrors := make(chan error, 1)
+
+	go func() {
+		defer close(filteredChanges)
+		defer close(filteredErrors)
+
+		for {
+			select {
+			case <-ctx.Done():
+				filteredErrors <- ctx.Err()
+				return
+			case err, ok := <-errs:
+				if !ok {
+					errs = nil
+					continue
+				}
+				if err != nil {
+					filteredErrors <- err
+					return
+				}
+			case change, ok := <-changes:
+				if !ok {
+					return
+				}
+
+				originalRelationshipCount := len(change.RelationshipChanges)
+				change.RelationshipChanges = change.RelationshipChanges[:0]
+				for _, relationshipChange := range change.RelationshipChanges {
+					panic("unreachable")
+				}
+				_ = originalRelationshipCount
+				_ = version
+				filteredChanges <- change
+			}
+		}
+	}()
+
+	return filteredChanges, filteredErrors
+}
