		return t.rwt.BulkLoad(ctx, iter)
	}

	relationships := make([]tuple.Relationship, 0)
	for {
		relationship, err := iter.Next(ctx)
		if err != nil {
			return 0, err
		}
		if relationship == nil {
			break
		}
		relationships = append(relationships, *relationship)
